    pub worktree: Option<WorktreeIdentity>,
    pub cwd: Option<String>,
    pub cols: u16,
    pub rows: u16,
    pub running: bool,
    pub start_sequence: Option<u64>,
    pub end_sequence: Option<u64>,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
