        let real_socket = dir.path().join("real.sock");
        let _listener = UnixListener::bind(&real_socket).unwrap();
        let symlink_socket = dir.path().join("daemon.sock");
        std::os::unix::fs::symlink(&real_socket, &symlink_socket).unwrap();
        let client = DaemonClient::new_with_socket(symlink_socket);
        let error = client.connect_or_spawn().await.expect_err("symlinked daemon socket must fail closed");
